/** Shape of src/data/kosa-generated/curatedCanon.ts (generated by scripts/build-citation-check.ts). */
export interface CuratedCanonHan {
  /** CBETA canon number the wording is taken from. */
  sourceId: string;
  title: string;
  /** Translator line of that text (CBETA <byline>). */
  byline: string;
  coverage: number;
  precision: number;
  /** Source wording, one string per entry verse (interlinear notes kept as in CBETA). */
  verses: string[];
}

export interface CuratedCanonSanskrit {
  file: string;
  url: string;
  coverage: number;
  precision: number;
  verses: string[];
}

export interface CuratedCanonRecord {
  han?: CuratedCanonHan;
  sanskrit?: CuratedCanonSanskrit;
}
